// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint8 seed) public {
        amount1 = bound(amount1, 1 ether, 100 ether);
        amount2 = bound(amount2, 1 ether, 100 ether);
        address eoa = address(uint160(uint256(keccak256(abi.encode(seed)))));
        vm.assume(eoa != address(0) && eoa != address(this) && eoa != address(c));

        Proxy proxy = new Proxy(address(c));

        vm.deal(address(proxy), amount1);
        vm.deal(eoa, amount2);

        uint256 balProxyBefore = c.getBalance(address(proxy));
        uint256 balEoaBefore = c.getBalance(eoa);
        uint256 cBalBefore = address(c).balance;

        vm.prank(address(proxy));
        proxy.forward{value: amount1}();

        vm.prank(eoa);
        c.addToBalance{value: amount2}();

        uint256 balProxyAfter = c.getBalance(address(proxy));
        uint256 balEoaAfter = c.getBalance(eoa);
        uint256 cBalAfter = address(c).balance;

        uint256 totalUserBal = balProxyAfter + balEoaAfter;
        uint256 totalReceived = cBalAfter - cBalBefore;
        assertTrue(totalUserBal == totalReceived);
    }
}

contract Proxy {
    Reentrance public target;
    constructor(address _target) { target = Reentrance(_target); }
    function forward() external payable {
        target.addToBalance{value: msg.value}();
    }
    receive() external payable {}
}
